import type { MediaRow } from "../domain";
import type { Locale } from "../i18n";
import { esc } from "../utils";

export type MediaCardRow = MediaRow & {
  like_count?: number;
  viewer_liked?: number;
};

type MediaCardOptions = {
  code?: string;
  locale?: Locale;
  selectable?: boolean;
  deferredSelection?: boolean;
  manage?: boolean;
  lightbox?: boolean;
  reportCode?: string;
  likes?: boolean;
  likesReadonly?: boolean;
  showUploader?: boolean;
  downloads?: boolean;
  deferAfter?: number;
  coverControl?: {
    eventCode: string;
    locale: Locale;
    activeMediaId?: string | null;
  };
};

type SelectionAction = {
  buttonId: string;
  label: string;
  kind: "download" | "submit";
  formId?: string;
  inputId?: string;
  confirmMessage?: string;
  requireSingle?: boolean;
  mediaType?: "image" | "video";
};

type BulkSelectionScriptOptions = {
  selectButtonId: string;
  cardSelector: string;
  selectorSelector: string;
  checkboxSelector: string;
  tickSelector: string;
  selectText: string;
  cancelText: string;
  actions: SelectionAction[];
};

