  const doubleHeart = likes ? `<span id="lightbox-double-heart" aria-hidden="true" class="pointer-events-none absolute left-1/2 top-1/2 z-40 -translate-x-1/2 -translate-y-1/2 text-white drop-shadow-2xl"><svg viewBox="0 0 24 24" class="h-28 w-28 fill-rose-500 text-white" stroke="currentColor" stroke-width="1.2"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78Z"/></svg></span>` : "";
  return `<dialog id="media-lightbox" aria-label="${esc(copy.lightbox)}" class="h-screen w-screen max-h-none max-w-none bg-transparent p-0 backdrop:bg-black/85"><div id="lightbox-stage" class="relative flex h-full w-full items-center justify-center p-4 sm:p-12"><button id="lightbox-prev" aria-label="${esc(copy.previous)}" class="absolute left-3 z-20 hidden h-12 w-12 items-center justify-center rounded-full bg-white/15 text-3xl text-white sm:left-6 sm:flex">‹</button><div id="lightbox-content" class="flex max-h-full max-w-full flex-col items-center"></div><button id="lightbox-next" aria-label="${esc(copy.next)}" class="absolute right-3 z-20 hidden h-12 w-12 items-center justify-center rounded-full bg-white/15 text-3xl text-white sm:right-6 sm:flex">›</button>${lightboxLike}${doubleHeart}</div></dialog><script>(()=>{const items=[...document.querySelectorAll('.lightbox-item')],dialog=document.getElementById('media-lightbox'),content=document.getElementById('lightbox-content'),stage=document.getElementById('lightbox-stage'),title=document.getElementById('lightbox-title'),likeButton=document.getElementById('lightbox-like'),doubleHeart=document.getElementById('lightbox-double-heart');let index=0;const activeItems=()=>items.filter(item=>!item.closest('[data-media-type]')?.classList.contains('hidden'));const resetPosition=()=>{content.style.transition='none';content.style.transform='translateX(0) scale(1)';content.style.opacity='1'};const syncLike=item=>{if(!likeButton)return;const visible=item.dataset.type==='image'&&item.dataset.mediaId;if(!visible){likeButton.classList.add('hidden');likeButton.classList.remove('inline-flex');return}const liked=item.dataset.liked==='true',heart=likeButton.querySelector('[data-like-heart]'),counter=likeButton.querySelector('[data-like-count]');likeButton.dataset.mediaId=item.dataset.mediaId;likeButton.setAttribute('aria-pressed',String(liked));likeButton.setAttribute('aria-label',liked?${JSON.stringify(unlikeLabel)}:${JSON.stringify(likeLabel)});likeButton.classList.remove('hidden');likeButton.classList.add('inline-flex');if(counter)counter.textContent=item.dataset.likeCount||'0';if(heart){heart.classList.toggle('fill-rose-500',liked);heart.classList.toggle('text-rose-500',liked);heart.classList.toggle('fill-transparent',!liked);heart.classList.toggle('text-white',!liked)}};const show=i=>{const available=activeItems();if(!available.length)return;index=(i+available.length)%available.length;resetPosition();const item=available[index],src=item.dataset.src,full=item.dataset.full||src;content.innerHTML=item.dataset.type==='video'?'<video src="'+src+'" controls autoplay playsinline class="max-h-[80vh] max-w-[86vw] rounded-xl"></video>':'<img src="'+src+'" alt="" draggable="true" class="native-save-image max-h-[80vh] max-w-[86vw] touch-manipulation select-none rounded-xl object-contain">';const visibleImage=content.querySelector('.native-save-image');if(visibleImage&&full!==src){const original=new Image();original.onload=()=>{if(content.contains(visibleImage)&&activeItems()[index]===item){visibleImage.src=full;visibleImage.dataset.fullResolution='true'}};original.src=full}if(title)title.textContent=item.dataset.title||'';syncLike(item)};const showDoubleHeart=()=>{if(!doubleHeart)return;doubleHeart.classList.remove('lightbox-heart-pop');void doubleHeart.offsetWidth;doubleHeart.classList.add('lightbox-heart-pop')};items.forEach(item=>item.onclick=()=>{show(activeItems().indexOf(item));dialog.showModal()});document.getElementById('lightbox-prev').onclick=()=>show(index-1);document.getElementById('lightbox-next').onclick=()=>show(index+1);let touchX=0,touchY=0,dragX=0,dragging=false,tapStartedOnImage=false,lastTapAt=0,lastTapX=0,lastTapY=0;dialog.addEventListener('touchstart',e=>{if(!dialog.open||!e.touches.length)return;const touch=e.touches[0];touchX=touch.clientX;touchY=touch.clientY;dragX=0;dragging=false;tapStartedOnImage=Boolean(e.target.closest?.('.native-save-image'));content.style.transition='none'},{passive:true});dialog.addEventListener('touchmove',e=>{if(!dialog.open||!e.touches.length)return;const touch=e.touches[0],dx=touch.clientX-touchX,dy=touch.clientY-touchY;if(!dragging&&Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy))dragging=true;if(!dragging)return;e.preventDefault();dragX=dx;lastTapAt=0;const scale=1-Math.min(Math.abs(dx)/window.innerWidth,1)*.04;content.style.transform='translateX('+dx+'px) scale('+scale+')';content.style.opacity=String(1-Math.min(Math.abs(dx)/window.innerWidth,.35))},{passive:false});dialog.addEventListener('touchend',e=>{if(!dragging){resetPosition();const touch=e.changedTouches[0],now=Date.now(),isDouble=tapStartedOnImage&&touch&&now-lastTapAt<340&&Math.hypot(touch.clientX-lastTapX,touch.clientY-lastTapY)<36;if(isDouble){e.preventDefault();const item=activeItems()[index];if(item?.dataset.type==='image'&&likeButton){if(item.dataset.liked!=='true'&&likeButton.dataset.busy!=='1')likeButton.click();showDoubleHeart()}lastTapAt=0}else if(tapStartedOnImage&&touch){lastTapAt=now;lastTapX=touch.clientX;lastTapY=touch.clientY}else lastTapAt=0;tapStartedOnImage=false;return}content.style.transition='transform 180ms ease-out, opacity 180ms ease-out';if(Math.abs(dragX)>60){content.style.transform='translateX('+(dragX<0?'-110vw':'110vw')+') scale(.96)';content.style.opacity='0';setTimeout(()=>show(dragX<0?index+1:index-1),180)}else{content.style.transform='translateX(0) scale(1)';content.style.opacity='1'}dragging=false;tapStartedOnImage=false;lastTapAt=0},{passive:false});dialog.onclick=e=>{if(e.target===dialog||e.target===stage)dialog.close()};document.addEventListener('keydown',e=>{if(!dialog.open)return;if(e.key==='ArrowLeft')show(index-1);if(e.key==='ArrowRight')show(index+1);if(e.key==='Escape')dialog.close()})})()<\/script>`;
